[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "<div class="print-heading">				<h2><div>Appointment Letter Template</div><br><small class="sub-heading">{{ _(doc.name) }}</small>				</h2></div>"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "{% set employee_name = doc.employee_name or doc.name %}
{% set appointment_date = doc.date_of_joining or doc.creation %}
{% set cnic = doc.get("cnic") or doc.get("custom_cnic") or doc.get("passport_number") or "-" %}
{% set father_name = doc.get("father_name") or doc.get("custom_father_name") or "-" %}
{% set phone = doc.cell_number or doc.personal_phone or "-" %}
{% set address = doc.current_address or doc.permanent_address or "-" %}
{% set designation = doc.designation or "-" %}
{% set department = doc.department or "-" %}
{% set madrasa = doc.get("custom_madrasa") or doc.get("madrasa") or "-" %}
{% set city = doc.get("custom_city") or doc.get("city") or "-" %}
{% set salary = doc.ctc or 0 %}
{% set salary_currency = doc.salary_currency or frappe.db.get_default("currency") or "PKR" %}
{% set joining_date = doc.date_of_joining or "" %}

<style>
.print-format {
    padding: 0;
    margin: 0;
    font-family: "Noto Nastaliq Urdu", "Jameel Noori Nastaleeq", serif;
    color: #000;
}

.appointment-page {
    width: 100%;
    min-height: 100%;
    padding: 12mm 10mm;
    direction: rtl;
    font-size: 12px;
    line-height: 1.8;
}

.header {
    text-align: center;
    margin-bottom: 10px;
}

.header img {
    max-width: 78%;
    max-height: 85px;
}

.title-bar {
    background: #000;
    color: #fff;
    text-align: center;
    font-weight: bold;
    padding: 3px 10px;
    margin: 8px auto 10px;
    width: 55%;
    font-size: 13px;
}

.info-grid {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 8px;
}

.info-grid td {
    padding: 2px 4px;
    vertical-align: bottom;
    white-space: nowrap;
}

.label {
    font-weight: bold;
    width: 10%;
}

.value {
    border-bottom: 1px solid #000;
    min-width: 120px;
    text-align: center;
    font-family: Arial, sans-serif;
    direction: ltr;
}

.value-urdu {
    border-bottom: 1px solid #000;
    min-width: 120px;
    text-align: center;
}

.wide {
    min-width: 210px;
}

.salary-row {
    margin-top: 5px;
}

.signature {
    margin-top: 35px;
    width: 180px;
    text-align: center;
}

.signature-line {
    border-top: 1px solid #000;
    padding-top: 4px;
}

.terms-title {
    text-align: center;
    font-weight: bold;
    margin-top: 16px;
    margin-bottom: 4px;
}

.terms {
    font-size: 10.5px;
    line-height: 1.9;
    margin-top: 4px;
}

.terms li {
    margin-bottom: 2px;
}

.bottom-sign {
    margin-top: 18px;
    text-align: left;
    font-weight: bold;
}

@media print {
    @page {
        size: A4 portrait;
        margin: 8mm;
    }

    .appointment-page {
        page-break-inside: avoid;
    }
}
</style>

<div class="appointment-page">

    <div class="header">
        {# Replace this src with your uploaded letter head image path if needed #}
        <img src="/assets/donation_management/images/jtq-letter-head.png">
    </div>

    <div class="title-bar">
        آغاز تقرر نامہ برائے معلم / معلمہ
    </div>

    <table class="info-grid">
        <tr>
            <td class="label">فارم نمبر</td>
            <td class="value">{{ doc.name }}</td>
            <td class="label">کوڈ نمبر</td>
            <td class="value">{{ doc.get("attendance_device_id") or "-" }}</td>
            <td class="label">تاریخ</td>
            <td class="value">{{ frappe.utils.formatdate(appointment_date) }}</td>
        </tr>
        <tr>
            <td class="label">مرکز</td>
            <td class="value-urdu">{{ madrasa }}</td>
            <td class="label">ولایت</td>
            <td class="value-urdu">{{ city }}</td>
            <td class="label">شناختی کارڈ نمبر</td>
            <td class="value">{{ cnic }}</td>
        </tr>
        <tr>
            <td class="label">موجودہ پتہ</td>
            <td class="value-urdu wide" colspan="3">{{ address }}</td>
            <td class="label">موبائل نمبر</td>
            <td class="value">{{ phone }}</td>
        </tr>
        <tr>
            <td class="label">نام معلم</td>
            <td class="value-urdu">{{ employee_name }}</td>
            <td class="label">ولدیت</td>
            <td class="value-urdu">{{ father_name }}</td>
            <td class="label">تعلیم</td>
            <td class="value-urdu">{{ doc.get("qualification") or doc.get("custom_qualification") or "-" }}</td>
        </tr>
        <tr>
            <td class="label">عہدہ</td>
            <td class="value-urdu">{{ designation }}</td>
            <td class="label">شعبہ</td>
            <td class="value-urdu">{{ department }}</td>
            <td class="label">تاریخ تقرر</td>
            <td class="value">{{ frappe.utils.formatdate(joining_date) if joining_date else "-" }}</td>
        </tr>
        <tr>
            <td class="label">ماہانہ مشاہرہ</td>
            <td class="value">{{ frappe.utils.fmt_money(salary, currency=salary_currency) }}</td>
            <td class="label">رہائش الاؤنس</td>
            <td class="value">{{ frappe.utils.fmt_money(doc.get("custom_residence_allowance") or 0, currency=salary_currency) }}</td>
            <td class="label">کل مشاہرہ</td>
            <td class="value">{{ frappe.utils.fmt_money((salary or 0) + (doc.get("custom_residence_allowance") or 0), currency=salary_currency) }}</td>
        </tr>
    </table>

    <p>
        آپ کو ٹرسٹ جمعیت تعلیم القرآن کے تحت بحیثیت {{ designation }} مقرر کیا جاتا ہے۔
        آپ کی خدمات ادارے کے قواعد و ضوابط کے مطابق ہوں گی۔
    </p>

    <div class="signature">
        <div class="signature-line">منیجر ایچ آر</div>
    </div>

    <div class="terms-title">ضروری ہدایات</div>

    <ul class="terms">
        <li>آپ ادارے کے تمام قواعد و ضوابط کی پابندی کریں گے۔</li>
        <li>ڈیوٹی کے اوقات کی پابندی لازم ہوگی۔ غیر حاضری کی صورت میں ادارے کے قواعد لاگو ہوں گے۔</li>
        <li>ادارہ ضرورت کے مطابق آپ کی ذمہ داری، مقام یا شعبہ تبدیل کرنے کا حق محفوظ رکھتا ہے۔</li>
        <li>آپ ادارے کی اجازت کے بغیر کسی دوسری جگہ ملازمت یا تدریسی ذمہ داری انجام نہیں دیں گے۔</li>
        <li>ادارے کی املاک، ریکارڈ اور معلومات کی حفاظت آپ کی ذمہ داری ہوگی۔</li>
        <li>تقرر عارضی/مشروط بنیاد پر ہوگا اور کارکردگی کی بنیاد پر جاری رکھا جائے گا۔</li>
        <li>کسی بھی خلاف ورزی کی صورت میں ادارہ قانونی/انتظامی کارروائی کا حق رکھتا ہے۔</li>
    </ul>

    <div class="bottom-sign">
        دستخط ملازم: ____________________
    </div>

</div>"}]

[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "<div class="print-heading">				<h2><div>Appointment Letter Template</div><br><small class="sub-heading">{{ _(doc.name) }}</small>				</h2></div>"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "{% set employee_name = doc.employee_name or doc.name %}
{% set employee_address = doc.current_address or doc.permanent_address or "" %}
{% set designation = doc.designation or "Assistant Manager Administration" %}
{% set joining_date = doc.date_of_joining or doc.creation %}
{% set appointment_date = doc.get("custom_appointment_date") or joining_date %}
{% set basic_salary = doc.get("custom_basic_salary") or doc.ctc or 0 %}
{% set medical_allowance = doc.get("custom_medical_allowance") or 0 %}
{% set salary_currency = doc.salary_currency or frappe.db.get_default("currency") or "PKR" %}

<style>
.print-format {
    padding: 0 !important;
    margin: 0 !important;
    font-family: "Times New Roman", Times, serif;
    color: #000;
    font-size: 12px;
    line-height: 1.28;
}

.appointment-page {
    width: 100%;
    min-height: 277mm;
    padding: 34mm 26mm 24mm 26mm;
    box-sizing: border-box;
    page-break-after: always;
}

.appointment-page:last-child {
    page-break-after: auto;
}

.date-line {
    text-align: right;
    margin-bottom: 28px;
}

.address-block {
    white-space: pre-line;
    margin-bottom: 34px;
}

.title {
    text-align: center;
    font-weight: bold;
    text-decoration: underline;
    font-size: 15px;
    margin-bottom: 26px;
}

.para {
    text-align: justify;
    margin-bottom: 13px;
}

.bold {
    font-weight: bold;
}

.underline {
    text-decoration: underline;
}

.section-title {
    margin-top: 14px;
    margin-bottom: 10px;
    font-weight: bold;
}

.salary-table {
    margin-left: 38px;
    margin-bottom: 24px;
    border-collapse: collapse;
}

.salary-table td {
    padding: 1px 10px 1px 0;
    vertical-align: top;
}

.terms {
    margin: 0;
    padding-left: 28px;
}

.terms li {
    margin-bottom: 15px;
    text-align: justify;
    padding-left: 4px;
}

.page-two {
    padding-top: 70mm;
}

.close-text {
    margin-top: 22px;
    font-style: italic;
    text-align: justify;
}

.signature-block {
    margin-top: 25px;
}

.manager {
    margin-top: 62px;
}

.acceptance {
    margin-top: 70px;
    font-style: italic;
}

.employee-sign {
    margin-top: 42px;
    line-height: 2.6;
}

@media print {
    @page {
        size: A4 portrait;
        margin: 0;
    }

    .appointment-page {
        page-break-after: always;
    }

    .appointment-page:last-child {
        page-break-after: auto;
    }
}
</style>

<div class="appointment-page">

    <div class="date-line">
        Date:
        <span class="bold">
            {{ frappe.utils.formatdate(appointment_date, "dd MMMM yyyy") }}
        </span>
    </div>

    <div class="address-block">
        <span class="bold">{{ employee_name }}</span>
        {% if employee_address %}
{{ employee_address }}
        {% endif %}
    </div>

    <div class="title">APPOINTMENT LETTER</div>

    <div class="para bold">
        Dear Mr. {{ employee_name }},
    </div>

    <div class="para">
        This is with reference to your employment application and your subsequent interviews with us.
        We are pleased to appoint you as
        <span class="bold">{{ designation }}</span>
        in
        <span class="bold">Education Department</span>
        with effect from
        <span class="bold">{{ frappe.utils.formatdate(joining_date, "dd MMMM yyyy") }}</span>.
    </div>

    <div class="para">
        A non-exhaustive list of the terms and conditions of your employment is provided as under:
    </div>

    <div class="section-title">
        A. &nbsp;&nbsp; REMUNERATION:
        <span style="font-weight: normal; margin-left: 22px;">
            (Your monthly gross salary break-up) :
        </span>
    </div>

    <table class="salary-table">
        <tr>
            <td>Basic Salary:</td>
            <td>Rs. {{ frappe.utils.fmt_money(basic_salary, currency=None) }} per Month</td>
        </tr>
        <tr>
            <td>Medical Allowance:</td>
            <td>
                Rs. {{ frappe.utils.fmt_money(medical_allowance, currency=None) }} per month
                {% if medical_allowance %}
                (After successful completion of probation period)
                {% endif %}
            </td>
        </tr>
    </table>

    <div class="para">
        In addition to the above, you shall be provided with other benefits proportionate to your grade
        as per organization policies.
    </div>

    <div class="section-title">
        B. &nbsp;&nbsp; TERMS AND CONDITIONS:
    </div>

    <ol class="terms">
        <li>
            The above break-up of Gross Salary may be modified according to organization’s policies
            however the gross salary as shown above will remain unchanged. Income tax and other
            applicable taxes will be borne by you as applicable.
        </li>

        <li>
            You will be on probation for a period of <span class="bold">Six (6) months</span> from the date
            of appointment, which may be extended at the sole discretion of the management. During
            the probationary period your services can be terminated without assigning any reason or notice thereof.
        </li>

        <li>
            After the successful completion of probationary period, either side may terminate the
            services after giving one calendar month notice in writing or one month gross salary in lieu thereof.
        </li>

        <li>
            The retirement age in our organization is set at sixty five (65) years. Such retirement age
            may be revised by the management, in their sole discretion, at any time.
        </li>

        <li>
            You will not disclose your salary and future compensations either directly or indirectly
            to any person within the organization.
        </li>

        <li>
            Your entitlement to avail leave will be in accordance with the organization policies,
            as framed and amended, from time to time.
        </li>

        <li>
            You may be transferred to any other department at the sole discretion of the management.
        </li>
    </ol>

</div>

<div class="appointment-page page-two">

    <ol class="terms" start="8">
        <li>
            You will be obligated to make good any loss or damage to the organization property caused
            by your negligence, inadvertence, fraud, carelessness or act or omission. Moreover, the
            termination of your service may not exonerate you from liability to make good this loss or damage.
        </li>

        <li>
            In case of breach of any of the terms of this appointment and any rules and regulations of
            service, or for any other misconduct, you will be subject to appropriate disciplinary action,
            as deemed fit by the management and which may lead to termination of your services.
        </li>

        <li>
            You will discharge all such duties, responsibilities and authorities as assigned to you,
            efficiently and diligently to the satisfaction of the management and you will not act in any
            manner contrary to the interest of the organization.
        </li>

        <li>
            You will promote the interest of the organization to the best of your abilities, skills and knowledge.
        </li>

        <li>
            During your employment or after its termination you will not disclose any information relating
            to the organization that you may obtain while you are in the service.
        </li>
    </ol>

    <div class="close-text">
        Kindly return the duplicate copy of this letter duly signed by you signifying your acceptance
        to the enclosed terms and conditions of this Appointment Letter.
    </div>

    <div class="signature-block">
        Yours Sincerely,<br>
        For <span class="bold">Trust Jamiat Talim-Ul-Quran</span>
    </div>

    <div class="manager">
        Manager HR
    </div>

    <div class="acceptance">
        I have read understood & hereby accept the above terms & conditions of appointment and
        agree to abide by the same.
    </div>

    <div class="employee-sign">
        <span class="bold">Signature:</span> _______________________________<br>
        <span class="bold">Name:</span> _______________________________<br>
        <span class="bold">Dated:</span> _______________________________
    </div>

</div>"}]
